import React, { useState } from 'react';

export default function TeacherActivities({ timetable, teachingSubject, userName }) {
  const [messages, setMessages] = useState([
    { id: 1, sender: `${userName || 'Buddhika Darshani'} (Teacher)`, text: 'ළමයි, Lesson 01 එකේ ගණිත ගැටළු වල මොනවා හරි නොවැටහෙන තැන් තියෙනවද?', isMe: true },
    { id: 2, sender: 'Amali Perera (Student)', text: 'නැහැ ටීචර්, වීඩියෝ එක බැලුවට පස්සේ ඔක්කොම ලස්සනට තේරුණා.', isMe: false }
  ]);
  const [typeText, setTypeText] = useState('');

  const handleSend = (e) => {
    e.preventDefault();
    if (!typeText.trim()) return;
    
    const newMsg = {
      id: Date.now(),
      sender: `${userName || 'Buddhika Darshani'} (Teacher)`,
      text: typeText,
      isMe: true
    };
    setMessages([...messages, newMsg]);
    setTypeText('');
    alert("💬 ඔබගේ පණිවිඩය සාර්ථකව සාකච්ඡා මණ්ඩපයට (Student Forum) එක් කරන ලදි!");
  };

  return (
    <div style={{ animation: 'fadeIn 0.5s', fontFamily: 'sans-serif', display: 'flex', flexDirection: 'column', gap: '25px' }}>
      
      {/* HEADER */}
      <div>
        <h2 style={{ color: '#1e293b', margin: 0, display: 'flex', alignItems: 'center', gap: '10px' }}>
          💬 Class Forum Space & Discussion Control
        </h2>
        <p style={{ color: '#64748b', fontSize: '14px', marginTop: '5px' }}>
          ගුරුවරුන් සහ සිසුන් අතර සජීවීව විෂය කරුණු ගැටළු සාකච්ඡා කිරීමේ නිල පුවරුව.
        </p>
      </div>

      {/* INTERACTIVE FORUM PANEL */}
      <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '16px', border: '1px solid #e2e8f0', boxShadow: '0 4px 15px rgba(0,0,0,0.01)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
          <h3 style={{ margin: 0, fontSize: '15px', color: '#1e293b', fontWeight: 'bold' }}>🗣️ Dynamic Active Stream ({teachingSubject || 'Mathematics'})</h3>
          <span style={{ fontSize: '11px', backgroundColor: '#dcfce7', color: '#16a34a', padding: '4px 10px', borderRadius: '20px', fontWeight: 'bold' }}>🟢 Portal Online</span>
        </div>

        {/* CHAT BUBBLES BUFFER */}
        <div style={{ border: '1px solid #cbd5e1', borderRadius: '12px', height: '280px', backgroundColor: '#f8fafc', padding: '20px', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {messages.map((m) => (
            <div 
              key={m.id} 
              style={{ 
                alignSelf: m.isMe ? 'flex-start' : 'flex-end', 
                backgroundColor: m.isMe ? '#e2e8f0' : '#dcfce7', 
                padding: '12px 16px', 
                borderRadius: '12px', 
                maxWidth: '70%', 
                fontSize: '13.5px',
                boxShadow: '0 2px 5px rgba(0,0,0,0.02)'
              }}
            >
              <strong style={{ display: 'block', fontSize: '11px', color: m.isMe ? '#475569' : '#16a34a', marginBottom: '4px' }}>
                {m.sender}
              </strong>
              {m.text}
            </div>
          ))}
        </div>

        {/* INPUT TRANSMITTER */}
        <form onSubmit={handleSend} style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
          <input 
            type="text" 
            placeholder="Type your official announcement or answer here..." 
            value={typeText}
            onChange={e => setTypeText(e.target.value)}
            style={{ flex: 1, padding: '12px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '13.5px', outline: 'none', backgroundColor: '#f8fafc' }} 
          />
          <button type="submit" style={{ backgroundColor: '#145c2e', color: 'white', border: 'none', padding: '0 25px', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13.5px' }}>
            Broadcast 🚀
          </button>
        </form>
      </div>

    </div>
  );
}
